<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateWriteGateway;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Connector\Pdo\TemplatePdoConnector;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateSlide;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateCursor;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateFilter;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;
use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class TemplateWriteRepositoryAdapter implements TemplateWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplatePdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(TemplateRef $ref): ?Template
    {
        return $this->conn->retrieveForUpdate(new TemplateFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?TemplateFilter $filter = null, ?TemplateCursor $cursor = null): TemplateSlide
    {
        $this->logDebug("List for update of Template on adapter ");
        $span = $this->startSpan("List for update of Template on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new TemplateSlide(function (TemplateSlide $slide, ?TemplateCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new TemplateCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(TemplateFilter $filter): ?Template
    {
        $this->logDebug("Retrieve for update of Template on adapter ");
        $span = $this->startSpan("Retrieve for update of Template on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(TemplateFilter $filter): bool
    {
        $this->logDebug("Exists for update of Template on adapter ");
        $span = $this->startSpan("Exists for update of Template on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?TemplateFilter $filter = null): int
    {
        $this->logDebug("Count for update of Template on adapter ");
        $span = $this->startSpan("Count for update of Template on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(Template $entity, ?Closure $verify = null): Template
    {
        $this->logDebug("Count for Template on adapter ");
        $span = $this->startSpan("Count for Template on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('template', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(TemplateRef $ref, Template $entity): Template
    {
        $this->logDebug("Count for Template on adapter ");
        $span = $this->startSpan("Count for Template on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('template', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(Template $entity): bool
    {
        $this->logDebug("Count for Template on adapter ");
        $span = $this->startSpan("Count for Template on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('template', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByCodeAndTenant(string $code, ?TenantRef $tenant): ?Template
    {
        $this->logDebug("Find on by code tenant for Template on adapter");
        $span = $this->startSpan("Find on by code tenant for Template on adapter");
        try {
            return $this->conn->retrieveForUpdate(new TemplateFilter(codeAndTenant: TemplateFilter::codeAndTenantFilter(code: $code, tenant: $tenant)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(Template $entity): void
    {
        $this->logDebug("Count for Template on adapter ");
        $span = $this->startSpan("Count for Template on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
